import { execSync } from 'child_process';
import fs from 'fs';
import path from 'path';
import zlib from 'zlib';

/**
 * Generates a valid 256x256 32-bit BGRA Windows Icon (.ico) file at
 * build/icon.ico and public/icon.ico directly from the 256x256 PNG
 * generated by scripts/generate-app-icons.py so the Windows .EXE icon
 * and Android .APK icon are 100% pixel-identical.
 */
function ensurePngIconsGenerated() {
  try {
    execSync('python3 scripts/generate-app-icons.py', { stdio: 'inherit' });
  } catch {
    try {
      execSync('python scripts/generate-app-icons.py', { stdio: 'inherit' });
    } catch (err) {
      console.warn('[Win Icon] Notice running generate-app-icons.py:', err?.message || err);
    }
  }
}

function decodeUnfilteredPng256(pngPath) {
  const buf = fs.readFileSync(pngPath);
  const idatChunks = [];
  let offset = 8; // Skip 8-byte PNG signature
  while (offset + 8 <= buf.length) {
    const length = buf.readUInt32BE(offset);
    const type = buf.toString('ascii', offset + 4, offset + 8);
    const dataStart = offset + 8;
    const dataEnd = dataStart + length;
    if (type === 'IDAT') {
      idatChunks.push(buf.subarray(dataStart, dataEnd));
    } else if (type === 'IEND') {
      break;
    }
    offset = dataEnd + 4; // Skip 4-byte CRC
  }
  const raw = zlib.inflateSync(Buffer.concat(idatChunks));
  const width = 256;
  const height = 256;
  const rgba = Buffer.alloc(width * height * 4);
  const stride = width * 4 + 1; // 1 filter byte (0) per row
  for (let y = 0; y < height; y++) {
    const srcStart = y * stride + 1;
    const dstStart = y * width * 4;
    raw.copy(rgba, dstStart, srcStart, srcStart + width * 4);
  }
  return rgba;
}

function generateValidWindowsIco() {
  const png256Path = path.resolve(process.cwd(), 'public', 'icons', 'icon-256x256.png');
  ensurePngIconsGenerated();

  const width = 256;
  const height = 256;
  const rgba = decodeUnfilteredPng256(png256Path);

  const xorSize = width * height * 4;
  const andRowBytes = Math.ceil(width / 32) * 4;
  const andSize = andRowBytes * height;
  const biSize = 40;
  const imageSize = biSize + xorSize + andSize;

  const buffer = Buffer.alloc(6 + 16 + imageSize, 0);

  // 1. ICONDIR Header
  buffer.writeUInt16LE(0, 0);
  buffer.writeUInt16LE(1, 2);
  buffer.writeUInt16LE(1, 4);

  // 2. ICONDIRENTRY
  buffer.writeUInt8(0, 6); // 256
  buffer.writeUInt8(0, 7); // 256
  buffer.writeUInt8(0, 8);
  buffer.writeUInt8(0, 9);
  buffer.writeUInt16LE(1, 10);
  buffer.writeUInt16LE(32, 12);
  buffer.writeUInt32LE(imageSize, 14);
  buffer.writeUInt32LE(22, 18);

  // 3. BITMAPINFOHEADER
  const dibOffset = 22;
  buffer.writeUInt32LE(biSize, dibOffset);
  buffer.writeInt32LE(width, dibOffset + 4);
  buffer.writeInt32LE(height * 2, dibOffset + 8);
  buffer.writeUInt16LE(1, dibOffset + 12);
  buffer.writeUInt16LE(32, dibOffset + 14);
  buffer.writeUInt32LE(0, dibOffset + 16);
  buffer.writeUInt32LE(xorSize + andSize, dibOffset + 20);

  const pixelOffset = dibOffset + biSize;

  // Write bottom-up BGRA pixels from top-down RGBA buffer
  for (let y = 0; y < height; y++) {
    const srcY = height - 1 - y;
    for (let x = 0; x < width; x++) {
      const sIdx = (srcY * width + x) * 4;
      const dIdx = pixelOffset + (y * width + x) * 4;
      buffer[dIdx] = rgba[sIdx + 2];     // B
      buffer[dIdx + 1] = rgba[sIdx + 1]; // G
      buffer[dIdx + 2] = rgba[sIdx];     // R
      buffer[dIdx + 3] = rgba[sIdx + 3]; // A
    }
  }

  const buildDir = path.resolve(process.cwd(), 'build');
  const publicDir = path.resolve(process.cwd(), 'public');
  if (!fs.existsSync(buildDir)) fs.mkdirSync(buildDir, { recursive: true });
  if (!fs.existsSync(publicDir)) fs.mkdirSync(publicDir, { recursive: true });

  fs.writeFileSync(path.join(buildDir, 'icon.ico'), buffer);
  fs.writeFileSync(path.join(publicDir, 'icon.ico'), buffer);
  console.log('Generated 256x256 Windows .ico for ESWA GEOLOGICAL MAPPER at build/icon.ico and public/icon.ico');
}

generateValidWindowsIco();
